:root {
  --bg: #f3f6fb;
  --panel: #ffffff;
  --panel-soft: #f8fafc;
  --line: #e5e7eb;
  --muted: #64748b;
  --text: #0f172a;
  --sidebar: #111827;
  --sidebar-soft: #1f2937;
  --primary: #2563eb;
  --primary-dark: #1d4ed8;
  --danger: #dc2626;
  --danger-dark: #b91c1c;
  --success: #16a34a;
  --warning: #f59e0b;
  --shadow: 0 8px 24px rgba(15, 23, 42, 0.06);
}

* { box-sizing: border-box; }
html, body { margin: 0; }
html {
  -webkit-text-size-adjust: 100%;
  text-size-adjust: 100%;
}
body {
  min-width: 320px;
  max-width: 100vw;
  overflow-x: hidden;
  font-family: Arial, Helvetica, sans-serif;
  background: var(--bg);
  color: var(--text);
}
img, svg, video, canvas { max-width: 100%; height: auto; }
button, input, select {
  font: inherit;
  max-width: 100%;
}
svg {
  display: block;
  width: 18px !important;
  height: 18px !important;
}
.app { display: flex; min-height: 100vh; }
.sidebar {
  width: 240px;
  background: var(--sidebar);
  color: #fff;
  padding: 20px 14px;
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.brand {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 5px 8px 18px;
}
.brand small {
  display: block;
  color: #9ca3af;
  margin-top: 2px;
}
.brand-logo {
  width: 48px;
  height: 48px;
  border-radius: 0;
  object-fit: contain;
  background: transparent;
  padding: 0;
  border: none;
  box-shadow: none;
  filter: none;
}
.nav {
  border: 0;
  background: transparent;
  color: #d1d5db;
  text-align: left;
  padding: 12px 12px;
  border-radius: 8px;
  font-size: 14px;
  cursor: pointer;
  display: flex;
  align-items: center;
  gap: 10px;
  transition: background 0.2s ease, color 0.2s ease;
}
.sub-nav-group {
  display: grid;
  gap: 4px;
  width: 100%;
  margin: 2px 0 4px 16px;
}
.sub-nav {
  width: 100%;
  padding: 10px 10px 10px 12px;
  font-size: 13px;
  background: rgba(148, 163, 184, 0.08);
}
.sub-nav:hover, .sub-nav.active {
  background: rgba(96, 165, 250, 0.14);
  color: #fff;
}
.nav:hover, .nav.active {
  background: var(--sidebar-soft);
  color: #fff;
}
.nav-icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 16px;
  height: 16px;
  flex-shrink: 0;
}
.nav-icon svg {
  width: 16px;
  height: 16px;
}
.side-bottom {
  margin-top: auto;
  color: #9ca3af;
  font-size: 12px;
  padding: 0 8px;
}
.app-status-footer {
  margin-top: 10px;
  padding-top: 10px;
  border-top: 1px solid #374151;
  display: grid;
  gap: 4px;
}
.app-status-footer b { color: #fff; }
.app-status-footer #connectionStatusText {
  font-weight: 700;
  text-transform: lowercase;
}
.login-badge {
  margin-top: 6px;
  color: #93c5fd;
  font-size: 12px;
}

.main {
  flex: 1;
  padding: 25px;
  min-width: 0;
}
header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 20px;
}
h1 { margin: 0; font-size: 25px; }
h2 { font-size: 18px; margin: 0 0 16px; }
header p { margin: 5px 0 0; color: var(--muted); }

.grid2 {
  display: grid;
  grid-template-columns: 1.7fr 0.8fr;
  gap: 18px;
}
.card {
  background: var(--panel);
  border: 1px solid var(--line);
  border-radius: 12px;
  padding: 20px;
  box-shadow: var(--shadow);
}
.row {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 12px;
}
.row, .card > label, .settings label {
  margin-bottom: 12px;
}
label {
  font-size: 12px;
  color: var(--muted);
  display: block;
}
input, select {
  width: 100%;
  border: 1px solid #d1d5db;
  border-radius: 7px;
  padding: 10px;
  margin-top: 6px;
  background: #fff;
  font-size: 14px;
  color: var(--text);
}
input:focus, select:focus {
  outline: none;
  border-color: #60a5fa;
  box-shadow: 0 0 0 3px rgba(96, 165, 250, 0.15);
}
#kasir input, #kasir select {
  background: linear-gradient(135deg, #f7f3ff 0%, #eef6ff 100%);
  border: 1px solid #d8c7ff;
  box-shadow: inset 0 1px 2px rgba(0,0,0,.03);
}
#kasir input::placeholder { color: #7c8aa0; }
.addline {
  display: grid;
  grid-template-columns: 1fr 90px 110px;
  gap: 8px;
  margin: 15px 0;
}
.addline select, .addline input { margin: 0; }

.btn {
  border: 1px solid #d1d5db;
  background: #fff;
  border-radius: 7px;
  padding: 10px 13px;
  cursor: pointer;
  font-weight: 600;
  color: var(--text);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  transition: filter 0.2s ease, transform 0.2s ease;
}
.btn:hover { filter: brightness(0.97); }
.btn:active { transform: translateY(1px); }
.primary { background: var(--primary); border-color: var(--primary); color: #fff; }
.primary:hover { background: var(--primary-dark); }
.success { background: var(--success); border-color: var(--success); color: #fff; }
.danger { background: var(--danger); border-color: var(--danger); color: #fff; }
.danger:hover { background: var(--danger-dark); }
.ghost { background: transparent; }
.wide { width: 100%; margin-top: 10px; }

.table-wrap { overflow: auto; }
table { width: 100%; border-collapse: collapse; font-size: 13px; }
th, td { padding: 10px 8px; border-bottom: 1px solid #eee; text-align: left; white-space: nowrap; }
th { color: #6b7280; background: #fafafa; }
.summary .sum {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 11px 0;
  border-bottom: 1px solid #eee;
}
.summary .sum input { width: 130px; }
.grand { font-size: 22px; }

.toolbar {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 10px;
  margin-bottom: 14px;
}
.product-toolbar {
  flex-wrap: wrap;
}
.toolbar-search {
  flex: 1 1 220px;
  min-width: 160px;
}
.toolbar-search input {
  width: 100%;
  margin: 0;
}
.toolbar-actions {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
}

.transaction-summary-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 14px;
  margin: 0 0 18px;
}
.transaction-metric {
  background: #fff;
  border: 1px solid var(--line);
  border-radius: 12px;
  padding: 18px 16px;
  box-shadow: 0 2px 8px rgba(0,0,0,.04);
}
.transaction-metric span {
  display: block;
  color: var(--muted);
  font-size: 12px;
  margin-bottom: 8px;
}
.transaction-metric b {
  display: block;
  font-size: 23px;
}
.transaction-filters {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin: 12px 0;
}
.transaction-filter {
  background: #f3f4f6;
  border: 1px solid var(--line);
  border-radius: 999px;
  padding: 7px 12px;
  font-size: 12px;
  font-weight: 700;
  color: #374151;
  cursor: pointer;
}
.transaction-filter.active {
  background: var(--primary);
  color: #fff;
  border-color: var(--primary);
}

.settings-group {
  margin-top: 18px;
  padding-top: 14px;
  border-top: 1px solid var(--line);
}
.settings-group h3 { margin: 0 0 10px; font-size: 15px; color: var(--text); }
.checkbox-group { display: grid; gap: 8px; margin: 8px 0 12px; }
.checkbox-inline {
  display: flex;
  align-items: center;
  gap: 8px;
  color: #374151;
  font-size: 13px;
}
.checkbox-inline input { width: auto; margin: 0; }

.settings-actions {
  display: flex;
  flex-wrap: nowrap;
  gap: 12px;
  margin-top: 18px;
}

.settings-actions .btn {
  flex: 1 1 0;
  min-width: 0;
}

.account-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 16px;
}
.account-subsection {
  margin-top: 18px;
}
.account-panel {
  background: #f8fafc;
  border: 1px solid var(--line);
  border-radius: 12px;
  padding: 18px;
  box-shadow: 0 2px 8px rgba(15, 23, 42, 0.04);
}
.activity-list {
  display: grid;
  gap: 10px;
}
.activity-item {
  border: 1px solid #e5e7eb;
  border-radius: 10px;
  background: #fff;
  padding: 10px 12px;
}
.activity-item.empty {
  color: #6b7280;
  text-align: center;
  padding: 12px;
}
.activity-top {
  display: flex;
  justify-content: space-between;
  gap: 8px;
  font-size: 11px;
  color: #6b7280;
  margin-bottom: 5px;
}
.activity-action {
  font-weight: 700;
  color: #111827;
  margin-bottom: 4px;
}
.activity-detail {
  font-size: 12px;
  color: #475569;
  line-height: 1.4;
}
.compact-table table {
  min-width: 100%;
  font-size: 12px;
}
.compact-table th,
.compact-table td {
  padding: 8px 6px;
}

.account-action-row,
.account-secondary-actions,
.danger-zone {
  display: block;
  margin-top: 12px;
}

.account-action-row .btn,
.account-secondary-actions .btn,
.danger-zone .btn {
  width: 100%;
  flex: none;
  min-width: 0;
}

#logoutBtn {
  background: linear-gradient(180deg, #ffffff 0%, #f8fafc 100%);
  border: 1px solid #d1d5db;
  color: #334155;
  box-shadow: 0 4px 10px rgba(15, 23, 42, 0.05);
}

#logoutBtn:hover {
  background: linear-gradient(180deg, #f8fafc 0%, #eef2ff 100%);
  border-color: #c7d2fe;
  color: #1e293b;
}

#logoutBtn svg {
  color: #475569;
}

@media (max-width: 767px) {
  .app {
    flex-direction: column;
  }
  .sidebar {
    width: 100%;
    padding: 12px 10px 8px;
    position: sticky;
    top: 0;
    z-index: 20;
    border-bottom: 1px solid rgba(148, 163, 184, 0.2);
  }
  .brand {
    padding: 2px 6px 10px;
  }
  .brand small {
    font-size: 11px;
  }
  .sidebar .nav {
    width: calc(50% - 4px);
    min-width: 0;
    padding: 10px 8px;
    font-size: 12px;
    justify-content: center;
  }
  .nav {
    text-align: center;
  }
  .nav-icon {
    margin-right: 0;
  }
  .side-bottom {
    padding: 0 8px 6px;
    font-size: 11px;
  }
  .main {
    padding: 16px 12px 24px;
  }
  header {
    margin-bottom: 16px;
  }
  h1 {
    font-size: 22px;
  }
  .grid2,
  .transaction-summary-grid,
  .stats,
  .dashboard-panels,
  .account-grid {
    grid-template-columns: 1fr !important;
  }
  .row,
  .addline {
    grid-template-columns: 1fr !important;
  }
  .app,
  .main,
  .page,
  .card,
  .sidebar {
    width: 100%;
    max-width: 100%;
  }
  .main {
    min-width: 0;
  }
  .toolbar {
    flex-direction: column;
    align-items: stretch;
  }
  .toolbar-actions {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 8px;
  }
  .toolbar-actions .btn {
    width: 100%;
    min-width: 0;
  }
  .card {
    padding: 16px;
  }
  .summary .sum {
    gap: 10px;
  }
  .summary .sum input {
    width: 110px;
    max-width: 100%;
  }
  .table-wrap {
    overflow-x: auto;
    -webkit-overflow-scrolling: touch;
  }
  table {
    min-width: 560px;
  }
  .settings-actions {
    flex-wrap: wrap;
  }
  .auth-overlay {
    padding: 16px;
  }
  .auth-box {
    flex-direction: column;
    min-height: auto;
  }
  .auth-main,
  .auth-side {
    width: 100%;
  }
  .auth-main {
    padding: 26px 18px 20px;
  }
  .auth-side {
    padding: 20px 16px 18px;
  }
  .auth-main-header h2 {
    font-size: clamp(1.8rem, 9vw, 2.7rem);
  }
  .auth-form {
    max-width: none;
  }
  .auth-side-brand {
    font-size: clamp(1.5rem, 7vw, 2.1rem);
  }
}

@media (min-width: 320px) and (max-width: 374px) {
  .sidebar .nav {
    width: 100%;
  }
  .toolbar-actions {
    grid-template-columns: 1fr;
  }
}

@media (min-width: 375px) {
  .brand {
    padding-left: 8px;
    padding-right: 8px;
  }
  .main {
    padding-left: 14px;
    padding-right: 14px;
  }
}

@media (min-width: 425px) {
  .sidebar .nav {
    width: calc(50% - 4px);
  }
  .toolbar-actions {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@media (min-width: 768px) {
  .app {
    display: flex;
    min-height: 100vh;
  }
  .sidebar {
    width: 240px;
    position: static;
    border-bottom: 0;
  }
  .sidebar .nav {
    width: auto;
    justify-content: flex-start;
    text-align: left;
  }
  .main {
    padding: 25px;
  }
  .grid2 {
    grid-template-columns: 1.7fr 0.8fr;
  }
  .row {
    grid-template-columns: 1fr 1fr;
  }
  .addline {
    grid-template-columns: 1fr 90px 110px;
  }
  .toolbar {
    flex-direction: row;
    justify-content: space-between;
    align-items: center;
  }
  .toolbar-actions {
    display: flex;
    flex-wrap: wrap;
    gap: 8px;
  }
  .transaction-summary-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
  .stats {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }
  .dashboard-panels {
    grid-template-columns: repeat(2, minmax(260px, 1fr));
  }
  .auth-box {
    flex-direction: row;
  }
  .auth-main {
    flex: 1.18;
  }
  .auth-side {
    flex: 0.9;
  }
}

@media (min-width: 1024px) {
  .main {
    padding: 28px 32px;
  }
  .transaction-summary-grid {
    grid-template-columns: repeat(4, minmax(0, 1fr));
  }
  .stats {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }
}

@media (min-width: 1440px) {
  .main {
    padding: 32px 38px;
  }
  .grid2 {
    gap: 22px;
  }
  .card {
    padding: 22px;
  }
}

.stats {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 15px;
  margin-bottom: 18px;
}
.dashboard-stats { grid-template-columns: repeat(3, minmax(0, 1fr)); }
.stat {
  background: #fff;
  border: 1px solid var(--line);
  border-radius: 12px;
  padding: 20px;
}
.stat small { display: block; color: var(--muted); }
.stat b { display: block; font-size: 23px; margin-top: 8px; }
.chart-tabs {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
  margin: 12px 0 16px;
}
.chart-tab {
  border: 1px solid #d1d5db;
  background: #fff;
  border-radius: 999px;
  padding: 7px 12px;
  font-size: 12px;
  font-weight: 700;
  cursor: pointer;
  color: #374151;
}
.chart-tab.active {
  background: var(--primary);
  color: #fff;
  border-color: var(--primary);
}
.chart-panel {
  background: #f9fafb;
  border: 1px solid var(--line);
  border-radius: 12px;
  padding: 12px;
  overflow: auto;
}
.dashboard-panels {
  display: grid;
  grid-template-columns: repeat(2, minmax(260px, 1fr));
  gap: 16px;
  margin-top: 18px;
}
.dashboard-panel {
  border: 1px solid var(--line);
  background: #fff;
  border-radius: 12px;
  padding: 16px;
}
.dashboard-panel h3 { margin: 0 0 12px; font-size: 16px; }
.dashboard-list { display: grid; gap: 10px; }
.order-row, .stock-row, .txn-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 10px;
  padding: 8px 0;
  border-top: 1px solid #f1f5f9;
}
.order-row:first-child, .stock-row:first-child, .txn-row:first-child { border-top: 0; }
.order-meta, .stock-meta, .txn-meta {
  display: flex;
  flex-direction: column;
  gap: 2px;
}
.badge {
  display: inline-block;
  padding: 3px 8px;
  border-radius: 999px;
  font-size: 11px;
  font-weight: 700;
}
.badge.diproses { background: #fef3c7; color: #92400e; }
.badge.baru { background: #dbeafe; color: #1d4ed8; }
.badge.selesai { background: #dcfce7; color: #166534; }
.badge.lunas { background: #dcfce7; color: #166534; }
.badge.dpp { background: #fef3c7; color: #92400e; }
.hidden { display: none !important; }

.modal {
  position: fixed;
  inset: 0;
  background: rgba(0,0,0,.55);
  display: grid;
  place-items: center;
  padding: 20px;
  z-index: 50;
}
.modal-box {
  background: #fff;
  width: min(430px, 100%);
  padding: 22px;
  border-radius: 12px;
  box-shadow: 0 16px 40px rgba(15, 23, 42, 0.18);
}
.modal-box input { margin-bottom: 8px; }
.import-modal-box { width: min(760px, 100%); }
.import-summary {
  margin: 10px 0 14px;
  padding: 10px 12px;
  border-radius: 8px;
  font-size: 13px;
}
.import-summary.success {
  background: #ecfdf5;
  color: #065f46;
  border: 1px solid #bbf7d0;
}
.import-summary.error {
  background: #fff1f2;
  color: #9f1239;
  border: 1px solid #fecdd3;
}
.import-preview-wrap { max-height: 320px; margin-bottom: 12px; }
.import-error-list { margin: 0 0 10px; padding-left: 20px; color: #b91c1c; font-size: 13px; }
.modal-actions {
  display: flex;
  justify-content: flex-end;
  gap: 8px;
  margin-top: 10px;
}
.remove {
  color: var(--danger);
  border: 0;
  background: none;
  cursor: pointer;
  font-weight: bold;
}
.mini { padding: 6px 8px; font-size: 12px; }

.barcode-wrap {
  display: flex;
  justify-content: center;
  align-items: center;
  margin: 2px auto 0;
  padding: 0;
  width: 100%;
}
.barcode-wrap svg {
  display: block;
  max-width: 100%;
  width: 100%;
  height: auto;
  max-height: 68px;
  background: #fff;
}
.receipt-orderno {
  font-size: 11px;
  text-align: center;
  margin-top: 1px;
  letter-spacing: 0.2px;
  line-height: 1.2;
}
.receipt-barcode-note {
  border-top: 1px dashed #000;
  margin: 2px 0 1px;
}

.auth-overlay {
  position: fixed;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 30px;
  z-index: 50;
  background-color: #dfe3e8;
  animation: authFadeIn 0.35s ease;
  isolation: isolate;
}
.auth-overlay::before {
  content: "";
  position: absolute;
  inset: 0;
  background-image: var(--login-bg-image, linear-gradient(135deg, rgba(15,23,42,0.72), rgba(30,41,59,0.86)));
  background-size: cover;
  background-position: center;
  background-repeat: no-repeat;
  filter: blur(var(--login-bg-blur, 0px)) brightness(var(--login-bg-brightness, 1));
  transform: scale(1.02);
}
.auth-overlay::after {
  content: "";
  position: absolute;
  inset: 0;
  background: rgba(15, 23, 42, var(--login-bg-overlay, 0.6));
}
.auth-overlay.hidden { display: none; }
.auth-box {
  position: relative;
  z-index: 1;
  width: min(900px, 100%);
  min-height: 460px;
  display: flex;
  background: #fff;
  border-radius: 8px;
  overflow: hidden;
  box-shadow: 0 18px 45px rgba(15, 23, 42, 0.12);
  animation: authSlideUp 0.4s ease;
  border: 1px solid rgba(148, 163, 184, 0.25);
}
.auth-main {
  flex: 1.18;
  background: #f8fafb;
  display: flex;
  flex-direction: column;
  justify-content: center;
  padding: 42px 48px 34px;
}
.auth-main-header {
  margin-bottom: 22px;
}
.auth-main-header h2 {
  margin: 0;
  font-size: clamp(2.4rem, 3vw, 3.4rem);
  line-height: 1.1;
  font-weight: 300;
  color: #111827;
  letter-spacing: -0.05em;
}
.auth-main-header p {
  margin: 10px 0 0;
  font-size: 1rem;
  color: #64748b;
}
.auth-form {
  display: grid;
  gap: 12px;
  max-width: 380px;
}
.auth-form .field-group {
  display: grid;
  gap: 8px;
}
.auth-form label {
