  min-height: 42px;
}
.login-theme-row input[type="color"] {
  width: 70px;
  height: 36px;
  min-width: 70px;
  padding: 0;
  border: 1px solid #d1d5db;
  border-radius: 8px;
  background: transparent;
  margin-top: 0;
}
.cashier-scene {
  position: relative;
  width: min(100%, 430px);
  height: 300px;
  margin: 14px auto 8px;
  background-image: url("data:image/png;base64,");
  background-repeat: no-repeat;
  background-position: center;
  background-size: contain;
  filter: drop-shadow(0 12px 18px rgba(0,0,0,0.14));
}
.cashier-scene > * {
  display: none !important;
}
.cashier-figure {
  position: absolute;
  left: 50%;
  bottom: 62px;
  transform: translateX(-50%);
  width: 150px;
  height: 150px;
}
.cashier-figure .head {
  position: absolute;
  left: 50%;
  top: 0;
  width: 52px;
  height: 52px;
  transform: translateX(-50%);
  border-radius: 50%;
  background: #f7d7b3;
  box-shadow: inset 0 -4px 0 rgba(0,0,0,0.04);
}
.cashier-figure .head::before,
.cashier-figure .head::after {
  content: "";
  position: absolute;
  width: 6px;
  height: 6px;
  background: #1f2937;
  border-radius: 50%;
  top: 22px;
}
.cashier-figure .head::before { left: 16px; }
.cashier-figure .head::after { right: 16px; }
.cashier-figure .body {
  position: absolute;
  left: 50%;
  top: 52px;
  width: 92px;
  height: 68px;
  transform: translateX(-50%);
  background: linear-gradient(180deg, #f5f5f5, #e5e7eb);
  border-radius: 20px 20px 18px 18px;
  box-shadow: inset 0 -8px 0 rgba(0,0,0,0.04);
}
.cashier-figure .body::before {
  content: "";
  position: absolute;
  left: 50%;
  bottom: 12px;
  width: 58px;
  height: 18px;
  transform: translateX(-50%);
  border-radius: 8px;
  background: #d1fae5;
}
.cashier-figure .arm {
  position: absolute;
  width: 80px;
  height: 16px;
  border-radius: 999px;
  background: #f7d7b3;
  top: 66px;
}
.cashier-figure .arm-left {
  left: -16px;
  transform: rotate(22deg);
}
.cashier-figure .arm-right {
  right: -18px;
  transform: rotate(-28deg);
}
.cashier-figure .hand {
  position: absolute;
  width: 18px;
  height: 18px;
  background: #f7d7b3;
  border-radius: 50%;
  top: 90px;
}
.cashier-figure .hand-left { left: 12px; }
.cashier-figure .hand-right { right: 10px; }
.cashier-counter {
  position: absolute;
  left: 50%;
  bottom: 0;
  width: 245px;
  height: 120px;
  transform: translateX(-50%);
  background: linear-gradient(180deg, #eb4e4d 0%, #d93d3d 100%);
  border-radius: 16px 16px 8px 8px;
  box-shadow: inset 0 -8px 0 rgba(0,0,0,0.08);
}
.cashier-counter .counter-top {
  position: absolute;
  left: 10px;
  right: 10px;
  top: 18px;
  height: 18px;
  border-radius: 8px;
  background: rgba(255,255,255,0.18);
}
.cashier-screen {
  position: absolute;
  left: 50%;
  top: 46px;
  width: 90px;
  height: 12px;
  transform: translateX(-50%);
  border-radius: 10px;
  background: #1f2937;
  box-shadow: 0 0 0 4px rgba(255,255,255,0.12);
}
.counter-front {
  position: absolute;
  left: 18px;
  right: 18px;
  top: 66px;
  height: 34px;
  border-radius: 10px;
  background: rgba(255,255,255,0.08);
}

@keyframes authFadeIn {
  from { opacity: 0; }
  to { opacity: 1; }
}
@keyframes authSlideUp {
  from { opacity: 0; transform: translateY(12px); }
  to { opacity: 1; transform: translateY(0); }
}
@keyframes spin {
  to { transform: rotate(360deg); }
}

.account-header {
  display: flex;
  align-items: center;
  gap: 14px;
  padding-bottom: 18px;
  border-bottom: 1px solid var(--line);
  margin-bottom: 20px;
}
.account-header-icon {
  width: 48px;
  height: 48px;
  min-width: 48px;
  min-height: 48px;
  border-radius: 12px;
  background: linear-gradient(135deg, #dbeafe, #eff6ff);
  color: var(--primary);
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  box-shadow: inset 0 1px 0 rgba(255,255,255,0.5);
}
.account-header-icon svg,
.panel-title-icon svg,
.toggle-password svg,
.account-action-row .btn svg,
.account-secondary-actions .btn svg,
.danger-zone .btn svg {
  width: 18px !important;
  height: 18px !important;
  max-width: 18px;
  max-height: 18px;
  display: block;
  flex-shrink: 0;
}
.account-header-icon svg {
  width: 20px !important;
  height: 20px !important;
  max-width: 20px;
  max-height: 20px;
}
.account-header h2 { margin: 0 0 4px; }
.account-header p {
  margin: 0;
  color: var(--muted);
  font-size: 13px;
}
.account-grid {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(0, 1.3fr);
  gap: 18px;
}
.account-panel {
  background: var(--panel-soft);
  border: 1px solid var(--line);
  border-radius: 12px;
  padding: 18px;
}
.panel-title {
  display: flex;
  align-items: center;
  gap: 8px;
  font-weight: 700;
  color: var(--text);
  margin-bottom: 16px;
}
.panel-title-icon {
  width: 28px;
  height: 28px;
  border-radius: 8px;
  background: #e0f2fe;
  color: #0f766e;
  display: flex;
  align-items: center;
  justify-content: center;
}
.account-info-list { display: grid; gap: 12px; }
.account-info-item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
  padding: 12px 14px;
  border: 1px solid var(--line);
  border-radius: 10px;
  background: #fff;
}
.account-info-item span { color: var(--muted); font-size: 12px; }
.account-info-item strong { color: var(--text); font-size: 15px; }
.status-badge {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 5px 10px;
  border-radius: 999px;
  font-size: 12px;
  font-weight: 700;
}
.status-badge.active {
  background: #dcfce7;
  color: #166534;
}
.status-badge.inactive {
  background: #e5e7eb;
  color: #374151;
}
.field-group { display: grid; gap: 8px; }
.field-group label {
  font-size: 12px;
  font-weight: 600;
  color: #374151;
}
.password-field { position: relative; }
.password-field input { padding-right: 42px; }
.toggle-password {
  position: absolute;
  right: 10px;
  top: 50%;
  transform: translateY(-50%);
  width: 24px;
  height: 24px;
  border: none;
  background: transparent;
  color: #6b7280;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  padding: 0;
  border-radius: 6px;
}
.toggle-password:hover { background: #f3f4f6; }
.password-helper, .password-match-hint {
  font-size: 11px;
  color: var(--muted);
  line-height: 1.5;
}
.password-match-hint.error { color: #b91c1c; }
.password-match-hint.success { color: #166534; }
.password-strength { margin-top: 4px; }
.strength-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: 11px;
  color: #4b5563;
  margin-bottom: 6px;
}
.strength-status { font-weight: 700; }
.strength-bar {
  height: 8px;
  border-radius: 999px;
  background: #e5e7eb;
  overflow: hidden;
}
.strength-bar span {
  display: block;
  height: 100%;
  width: 0;
  border-radius: inherit;
  background: #ef4444;
  transition: width 0.2s ease, background 0.2s ease;
}
.strength-bar[data-level="weak"] span { background: #ef4444; }
.strength-bar[data-level="medium"] span { background: #f59e0b; }
.strength-bar[data-level="strong"] span { background: #10b981; }
.account-action-row, .account-secondary-actions, .danger-zone { margin-top: 6px; }
.account-action-row .btn, .account-secondary-actions .btn, .danger-zone .btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding-inline: 14px;
}
.account-secondary-actions .btn {
  background: #f8fafc;
  border-color: #e5e7eb;
  color: #374151;
}
.danger-zone {
  padding-top: 14px;
  border-top: 1px solid var(--line);
  margin-top: 18px;
}
.danger-zone .btn { width: 100%; }
.confirm-field.invalid .password-match-hint { color: #b91c1c; }
.confirm-field.valid .password-match-hint { color: #166534; }
.confirm-field.invalid input {
  border-color: #ef4444;
  box-shadow: 0 0 0 3px rgba(239, 68, 68, 0.08);
}
.confirm-field.valid input {
  border-color: #10b981;
  box-shadow: 0 0 0 3px rgba(16, 185, 129, 0.08);
}
.account-action-row .btn.primary {
  background: var(--primary);
  border-color: var(--primary);
}
.account-action-row .btn.primary:hover { background: var(--primary-dark); }
.account-secondary-actions .btn:hover { background: #f3f4f6; }
.danger-zone .btn {
  background: var(--danger);
  border-color: var(--danger);
}
.danger-zone .btn:hover { background: var(--danger-dark); }
.password-field input:focus, .confirm-field.invalid input:focus, .confirm-field.valid input:focus {
  outline: none;
  border-color: #60a5fa;
  box-shadow: 0 0 0 3px rgba(96, 165, 250, 0.15);
}

@media (max-width: 900px) {
  .sidebar { width: 190px; }
  .grid2 { grid-template-columns: 1fr; }
  .stats { grid-template-columns: 1fr; }
  .dashboard-stats { grid-template-columns: repeat(2, 1fr); }
  .transaction-summary-grid { grid-template-columns: repeat(2, 1fr); }
  .dashboard-panels { grid-template-columns: 1fr; }
  .account-grid { grid-template-columns: 1fr; }
}
@media (max-width: 650px) {
  .app { display: block; }
  .sidebar {
    width: 100%;
    flex-direction: row;
    overflow: auto;
    padding-bottom: 12px;
  }
  .brand { min-width: 190px; }
  .side-bottom { display: none; }
  .main { padding: 12px; }
  .row { grid-template-columns: 1fr; }
  .addline { grid-template-columns: 1fr 75px; }
  .addline .btn { grid-column: 1 / -1; }
  .toolbar-actions { justify-content: flex-start; }
  .transaction-summary-grid { grid-template-columns: 1fr; }
  .dashboard-stats { grid-template-columns: 1fr; }
  .account-header { align-items: flex-start; }
}

.toast {
  position: fixed;
  right: 18px;
  bottom: 18px;
  max-width: 320px;
  padding: 12px 14px;
  border-radius: 10px;
  color: #fff;
  background: #111827;
  opacity: 0;
  transform: translateY(10px);
  transition: opacity 0.2s ease, transform 0.2s ease;
  pointer-events: none;
}
.toast.show { opacity: 1; transform: translateY(0); }
.toast.success { background: #059669; }
.toast.error { background: #dc2626; }